{
  "name": "Pulsar任意波形发生器协调控制器",
  "name_en": "Pulsar AWG Orchestration Controller",
  "manufacturer": "",
  "description": "一个非物理的软件组件，用于在实验中统一管理、配置和编程一台或多台任意波形发生器（AWG）。它维护通道定义、查询时钟、协调主从AWG启动，并将序列与波形元素下发到受支持的AWG，证据显示其主要面向 Tektronix AWG5014，并部分支持 Zurich Instruments UHFLI。",
  "description_en": "A non-physical software component for centrally managing, configuring, and programming one or more arbitrary waveform generators (AWGs) in experiments. It keeps channel definitions, queries clock rates, coordinates master/slave AWG startup, and uploads sequences and waveform elements to supported AWGs. The evidence indicates primary support for the Tektronix AWG5014 and partial support for the Zurich Instruments UHFLI.",
  "actions": [
    {
      "action_name": "auto-define_channel",
      "description": "定义并登记AWG通道及其延迟、偏置、电平、激活状态和所属AWG，用于后续波形映射与控制。",
      "description_en": "Define and register an AWG channel with its delay, offset, levels, active state, and assigned AWG for later waveform mapping and control."
    },
    {
      "action_name": "auto-AWG_obj",
      "description": "根据AWG名称或通道名称返回对应的AWG对象，用于定位目标仪器。",
      "description_en": "Return the corresponding AWG object based on an AWG name or channel name to identify the target instrument."
    },
    {
      "action_name": "auto-clock",
      "description": "获取指定通道对应AWG的采样时钟速率。",
      "description_en": "Get the sampling clock rate of the AWG associated with a specified channel."
    },
    {
      "action_name": "auto-channel_opt",
      "description": "获取或设置已定义通道的配置选项。",
      "description_en": "Get or set a configuration option for a previously defined channel."
    },
    {
      "action_name": "auto-used_AWGs",
      "description": "返回当前已注册并处于活动使用状态的AWG名称集合。",
      "description_en": "Return the set of AWG names that are currently registered and actively used."
    },
    {
      "action_name": "auto-program_awgs",
      "description": "将实验序列和波形元素编程到一个或多个AWG，上传波形并设置段顺序、循环和触发等待。",
      "description_en": "Program one or more AWGs with an experimental sequence and waveform elements, uploading waveforms and setting segment order, looping, and trigger waiting."
    },
    {
      "action_name": "auto-update_channel_settings",
      "description": "根据当前保存的通道定义更新相关AWG的通道设置。",
      "description_en": "Update AWG channel settings based on the currently stored channel definitions."
    },
    {
      "action_name": "auto-update_AWG5014_settings",
      "description": "将保存的通道参数写入Tektronix AWG5014的设置中。",
      "description_en": "Apply the stored channel parameters to the settings of a Tektronix AWG5014."
    }
  ],
  "tag_hints": [
    "AWG orchestration",
    "multi-AWG synchronization",
    "waveform programming",
    "channel mapping",
    "master-slave triggering",
    "Tektronix AWG5014",
    "Zurich Instruments UHFLI"
  ]
}

